package com.codexpocket.app;

import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.os.Build;
import org.json.*;
import java.util.*;

/** Outgoing application notifications; separate from notification-reading authorization. */
final class AssistantNotifications {
    static final int PERMISSION=7502;static final String IMPORTANT="assistant_important",WORK="assistant_work",BACKGROUND="assistant_background";
    static void channels(Context c){NotificationManager m=c.getSystemService(NotificationManager.class);if(m==null)return;m.createNotificationChannel(new NotificationChannel(IMPORTANT,"重要事项与待办",NotificationManager.IMPORTANCE_DEFAULT));m.createNotificationChannel(new NotificationChannel(WORK,"工作结果与确认",NotificationManager.IMPORTANCE_DEFAULT));m.createNotificationChannel(new NotificationChannel(BACKGROUND,"后台运行状态",NotificationManager.IMPORTANCE_LOW));}
    static boolean allowed(Context c){return (Build.VERSION.SDK_INT<33||c.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)==PackageManager.PERMISSION_GRANTED)&&c.getSystemService(NotificationManager.class).areNotificationsEnabled();}
    static PendingIntent open(Context c,String work){Intent i=new Intent(c,MainActivity.class).setAction(work.isEmpty()?"com.codexpocket.app.OPEN_ASSISTANT":"com.codexpocket.app.OPEN_WORK").putExtra("assistant_work",work).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP|Intent.FLAG_ACTIVITY_CLEAR_TOP);return PendingIntent.getActivity(c,work.isEmpty()?7400:work.hashCode(),i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
    static Notification.Builder builder(Context c,String channel,String title,String text,String work){channels(c);Notification publicVersion=new Notification.Builder(c,channel).setSmallIcon(R.drawable.ic_notification).setContentTitle("Pocket Assistant").setContentText("有新的助理消息").build();return new Notification.Builder(c,channel).setSmallIcon(R.drawable.ic_notification).setContentTitle("Pocket Assistant").setContentText("有新的助理消息，请打开应用查看").setContentIntent(open(c,work)).setAutoCancel(true).setVisibility(Notification.VISIBILITY_PRIVATE).setPublicVersion(publicVersion);}
    private static void post(Context c,String key,String channel,String title,String text,String work){if(!allowed(c)||!c.getSharedPreferences("assistant_notifications",0).getBoolean(channel,true))return;try{Notification.Builder b=builder(c,channel,title,text,work);c.getSystemService(NotificationManager.class).notify(key,1,b.build());}catch(SecurityException ignored){}}
    static synchronized void important(Context c){try{List<JSONObject> rows=SmartRepository.visible(c);SharedPreferences p=c.getSharedPreferences("assistant_notifications",0);if(!allowed(c)||!p.getBoolean(IMPORTANT,true))return;NotificationLedger ledger=new NotificationLedger(p.getString("delivered","{}"));boolean changed=false;List<JSONObject> unseen=new ArrayList<>();long now=System.currentTimeMillis();for(JSONObject r:rows){String key="event:"+r.optString("notificationKey",r.optString("key"));if(ledger.claim(key,now)){changed=true;if(r.optLong("at")>=now-24*60*60*1000L)unseen.add(r);}}if(changed){p.edit().putString("delivered",ledger.data.toString()).apply();}if(!unseen.isEmpty()){JSONObject first=unseen.get(0);post(c,"important",IMPORTANT,unseen.size()>1?"有 "+unseen.size()+" 条重要事项":first.optString("title","新的重要事项"),first.optString("summary"),"");}}catch(Exception ignored){}}
    static synchronized void work(Context c,JSONObject r){String state=r.optString("state");if(!Arrays.asList("complete","failed","interrupted","approval").contains(state))return;SharedPreferences p=c.getSharedPreferences("assistant_notifications",0);String key="work:"+r.optString("id")+":"+state;if(!allowed(c)||!p.getBoolean(WORK,true))return;try{NotificationLedger ledger=new NotificationLedger(p.getString("delivered","{}"));if(!ledger.claim(key,System.currentTimeMillis()))return;p.edit().putString("delivered",ledger.data.toString()).apply();String title=state.equals("complete")?"工作已完成":state.equals("approval")?"电脑任务需要确认":"工作暂未完成";post(c,key,WORK,title,r.optString("prompt"),r.optString("id"));}catch(Exception ignored){}}
    static void task(Context c,String text){post(c,"manual-task",IMPORTANT,"已记入待办",text,"");}
    static void reply(Context c,String chat,boolean assistant,String title){if(!allowed(c)||!c.getSharedPreferences("assistant_notifications",0).getBoolean(WORK,true))return;try{Intent intent=new Intent(c,MainActivity.class).setAction("com.codexpocket.app.OPEN_REPLY").setData(android.net.Uri.parse("codexpocket://reply/"+(assistant?"assistant/":"android/")+chat)).putExtra("reply_chat",chat).putExtra("reply_assistant",assistant).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP|Intent.FLAG_ACTIVITY_CLEAR_TOP);PendingIntent open=PendingIntent.getActivity(c,0,intent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);c.getSystemService(NotificationManager.class).notify("reply:"+chat,1,builder(c,WORK,"回复已完成",title,"").setContentIntent(open).build());}catch(SecurityException ignored){}}
}
